const fs=require('node:fs'),vm=require('node:vm'),assert=require('node:assert/strict');
const html=fs.readFileSync('github-release/index.html','utf8'),scripts=[...html.matchAll(/<script[^>]*>([\s\S]*?)<\/script>/g)].map(m=>m[1]),box=vm.createContext({});
fs.writeFileSync(__dirname+'/baseline.html',html,{flag:'wx'});vm.runInContext(scripts[0],box);vm.runInContext(scripts[1].replace('return {actions,','return {threatCost,position,actions,'),box);
const E=box.Yiwu,C=box.YiwuComputer,runs=require('../king-rescue-v06119/known.json').slice(2),reports=[],fixtures=[];
for(const [runIndex,run]of runs.entries()){
  let s;const report={priorIndex:runIndex+2,plies:run.plies,boardStates:0,fullyCounteredThreats:0,affectedStates:0,fleeActions:0,examples:[]};
  for(const [index,[op,...args]]of run.commands.entries()){
    if(s?.phase==='board'&&['move','rest','pass'].includes(op)){
      report.boardStates++;let affected=false;
      for(const p of s.pieces.filter(p=>p.side===s.turn&&p.kind!=='king')){
        const threats=s.pieces.filter(q=>q.side!==p.side&&E.geometry(s,q,p.x,p.y,true));
        if(!threats.length)continue;
        const replies=threats.map(q=>({attacker:q.id,counters:Array.from(C.battleOutlook(s,E.context(s,q,p)).counters)}));
        if(!replies.every(r=>r.counters.length))continue;
        report.fullyCounteredThreats++;affected=true;
        if(op!=='move'||args[0]!==p.id||E.at(s,args[1],args[2]))continue;
        const next=JSON.parse(JSON.stringify(s));E.move(next,...args);
        if(C.threatCost(next,E.get(next,p.id)))continue;
        report.fleeActions++;
        if(report.examples.length<3){
          const detail={commandIndex:index,ply:s.ply,side:s.turn,piece:p.id,hp:p.hp,threatCost:C.threatCost(s,p),action:[op,...args],replies};
          report.examples.push(detail);fixtures.push({...detail,priorIndex:runIndex+2,commands:run.commands.slice(0,index)});
        }
      }
      if(affected)report.affectedStates++;
    }
    if(op==='create')s=E.create(...args);else E[op](s,...args);
  }
  assert.equal(s.phase,'ended');assert.equal(s.ply,run.plies);assert.equal(s.winner,run.winner);reports.push(report);
}
fs.writeFileSync(__dirname+'/probe.json',JSON.stringify({reports,fixtures},null,2)+'\n',{flag:'wx'});console.log(JSON.stringify(reports,null,2));

