const fs=require('node:fs'),vm=require('node:vm'),assert=require('node:assert/strict');
function model(file){const html=fs.readFileSync(file,'utf8'),scripts=[...html.matchAll(/<script[^>]*>([\s\S]*?)<\/script>/g)].map(m=>m[1]),box=vm.createContext({});vm.runInContext(scripts[0],box);vm.runInContext(scripts[1].replace('return {actions,','return {threatCost,actions,'),box);return {E:box.Yiwu,C:box.YiwuComputer};}
const baseline=model(__dirname+'/baseline.html'),candidate=model(__dirname+'/candidate.html'),{E,C}=candidate,copy=x=>JSON.parse(JSON.stringify(x));let checks=0,settlements=0,bounds=0;const diagnostics=[];
const test=(name,run)=>{run();checks++;console.log('通过：'+name);};
function verifyCounter(s,attacker,defender){
  const replies=C.choices(s,attacker,E.context(s,attacker,defender)),defenses=C.choices(s,defender,E.context(s,attacker,defender));
  return defenses.filter(id=>replies.every(reply=>{const next=copy(s);next.phase='duel';next.duel=E.context(next,E.get(next,attacker.id),E.get(next,defender.id));E.resolve(next,reply,id);settlements++;return !E.get(next,attacker.id)&&!!E.get(next,defender.id);}));
}
test('三份自然长局前缀及红黑旋转，可靠反杀不再计为普通受攻',()=>{
  for(const f of require('./probe.json').fixtures)for(const rotate of [false,true]){
    let s;for(const [op,...args]of f.commands){if(op==='create')s=E.create(...args);else E[op](s,...args);}
    if(rotate){s.turn=E.OTHER[s.turn];for(const p of s.pieces){p.side=E.OTHER[p.side];p.x=8-p.x;p.y=9-p.y;}}
    const defender=E.get(s,f.piece),before=JSON.stringify(s),attacks=s.pieces.filter(q=>q.side!==defender.side&&E.geometry(s,q,defender.x,defender.y,true));
    assert(attacks.length&&attacks.every(q=>verifyCounter(s,q,defender).length));assert(baseline.C.threatCost(s,defender)>0);assert.equal(C.threatCost(s,defender),0);
    const old=copy(baseline.C.rankedActions(s)).slice(0,4),next=copy(C.rankedActions(s)).slice(0,4);diagnostics.push({priorIndex:f.priorIndex,ply:s.ply,rotate,old,next});
    for(const difficulty of ['practice','standard'])for(const roll of [0,.5,.999999])assert(C.board(s,()=>roll,difficulty));assert.equal(JSON.stringify(s),before);
  }
});
test('高于1血、无法存活反杀或混有其他攻击者时，保留真实威胁',()=>{
  const s=E.create('attrition');s.pieces=[E.piece('rk','red','king',3,9),E.piece('bk','black','king',5,0),E.piece('hero','red','rook',4,5),E.piece('enemy','black','pawn',4,4)];s.repetitions={};const p=E.get(s,'hero'),q=E.get(s,'enemy');q.hp=1;
  assert(verifyCounter(s,q,p).length);assert.equal(C.threatCost(s,p),0);
  q.hp=2;assert(!verifyCounter(s,q,p).length);assert.equal(C.threatCost(s,p),baseline.C.threatCost(s,p));assert(C.threatCost(s,p)>0);
  q.hp=1;p.hp=1;assert(!verifyCounter(s,q,p).length);assert(C.threatCost(s,p)>0);
  p.hp=18;s.pieces.push(E.piece('extra','black','rook',0,5));assert(C.threatCost(s,p)>0);assert.equal(C.threatCost(s,p),baseline.C.threatCost(s,p));
});
test('基础反制招保证普通攻击者至少存活至1点伤害界限',()=>{
  const counter={strike:'guard',guard:'guard',break:'strike',focus:'guard'};
  for(const [id,card]of Object.entries({...E.BASE,...E.CARDS}))for(const forceA of [0,1,2])for(const forceD of [0,1,2])for(const support of [0,2]){
    const s=E.create('tactics'),a=E.get(s,'hero'),d=E.get(s,'target'),ctx=E.context(s,a,d);ctx.forceA=forceA;ctx.forceD=forceD;ctx.supportA=Array(support).fill('a');ctx.supportD=Array(2-support).fill('d');
    assert(E.roundDamage(ctx,counter[card.type],id).toA<=1);bounds++;
  }
});
test('挑战各棋子和普通将帅保留原评分',()=>{
  for(const scenario of ['challenge-support','challenge-relay','challenge-tempo','attrition']){
    const s=E.create(scenario);for(const p of s.pieces){const hp=p.hp;p.hp=1;for(const target of s.pieces.filter(q=>scenario!=='attrition'||q.kind==='king'))assert.equal(C.threatCost(s,target),baseline.C.threatCost(s,target));p.hp=hp;}
  }
});
fs.writeFileSync(__dirname+'/targeted.json',JSON.stringify({checks,actualSettlements:settlements,boundCases:bounds,diagnostics},null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({checks,actualSettlements:settlements,boundCases:bounds}));

